// AIM plugin for OpenCode v1. Generated by `aim install opencode`; edit with
// care, `aim install` overwrites this file.
//
// It spawns `aim hook opencode <event>` with a JSON payload on stdin and
// treats stdout as Markdown context for the session. Errors are swallowed:
// AIM must never break the agent.
//
// Remote approvals: OpenCode 1.x publishes permission.asked but no longer
// calls the permission.ask plugin hook, so the plugin forwards each asked
// permission to `aim hook opencode approve` while the terminal prompt shows,
// and replies through the SDK when the operator decides in the AIM console.
// Either answer wins; a terminal reply abandons the console's copy.
import { spawn } from "node:child_process"

const BIN = __AIM_BIN__
const HOOK_TIMEOUT_MS = 10_000
// The daemon ends an approval at its own timeout (at most an hour).
const APPROVE_TIMEOUT_MS = 3_630_000
const WAKE_CAP = 5
const WAKE_WINDOW_MS = 10 * 60_000

// run spawns the hook and resolves to its trimmed stdout ("" on any error).
// kill() stops it early.
function run(event, payload, timeoutMs) {
  let child
  const promise = new Promise((resolve) => {
    let out = ""
    let timer
    try {
      child = spawn(BIN, ["hook", "opencode", event], { stdio: ["pipe", "pipe", "ignore"] })
    } catch {
      resolve("")
      return
    }
    if (timeoutMs) timer = setTimeout(() => child.kill(), timeoutMs)
    child.stdout.on("data", (d) => (out += d))
    child.on("error", () => {
      clearTimeout(timer)
      resolve("")
    })
    child.on("close", () => {
      clearTimeout(timer)
      resolve(out.trim())
    })
    child.stdin.on("error", () => {})
    child.stdin.end(JSON.stringify(payload))
  })
  return { promise, kill: () => child && child.kill() }
}

function sessionOf(event) {
  const p = (event && event.properties) || {}
  return p.sessionID ?? (p.info && p.info.id) ?? p.id
}

// errorText extracts a message from a session.error event, if it has one.
function errorText(event) {
  const e = (event && event.properties && event.properties.error) || {}
  const m = (e.data && e.data.message) ?? e.message ?? e.name
  return typeof m === "string" ? m : ""
}

// permissionText names the permission being asked for, if the event does.
function permissionText(event) {
  const p = (event && event.properties) || {}
  const m = p.title ?? p.permission ?? p.type
  return typeof m === "string" ? m : ""
}

// approveRequest describes an asked permission for the console: the
// permission (tool) name, its title and its metadata plus patterns.
function approveRequest(p) {
  const meta = p.metadata && typeof p.metadata === "object" ? p.metadata : {}
  const patterns = p.patterns ?? (p.pattern === undefined ? [] : [].concat(p.pattern))
  const tool = p.permission ?? p.type
  return {
    tool: typeof tool === "string" ? tool : "",
    title: typeof p.title === "string" ? p.title : "",
    input: { ...meta, patterns },
  }
}

// parseDecision reads the approve hook's {"decision","reason"} line, or null.
function parseDecision(text) {
  try {
    const d = JSON.parse(text)
    if (d && (d.decision === "allow" || d.decision === "deny")) return d
  } catch {}
  return null
}

export const AimPlugin = async ({ client, directory }) => {
  const agents = new Map() // session id -> agent name
  const watchers = new Map() // session id -> in-flight watch
  const wakes = new Map() // session id -> wake timestamps
  const approvals = new Map() // permission id -> in-flight approve

  const payload = (sessionID) => ({ sessionID, directory, agent: agents.get(sessionID) ?? "" })

  const send = async (sessionID, text, wake) => {
    const parts = [{ type: "text", text }]
    const body = wake ? { parts } : { noReply: true, parts }
    await client.session.prompt({ path: { id: sessionID }, body })
  }

  const wakeAllowed = (sessionID) => {
    const now = Date.now()
    const recent = (wakes.get(sessionID) ?? []).filter((t) => now - t < WAKE_WINDOW_MS)
    wakes.set(sessionID, recent)
    return recent.length < WAKE_CAP
  }

  const inject = async (event, sessionID) => {
    const text = await run(event, payload(sessionID), HOOK_TIMEOUT_MS).promise
    if (text) await send(sessionID, text, false)
  }

  const startWatch = (sessionID) => {
    if (watchers.has(sessionID) || !wakeAllowed(sessionID)) return
    const w = run("watch", payload(sessionID), 0)
    watchers.set(sessionID, w)
    w.promise
      .then(async (text) => {
        if (watchers.get(sessionID) !== w) return
        watchers.delete(sessionID)
        if (!text || !wakeAllowed(sessionID)) return
        wakes.get(sessionID).push(Date.now())
        await send(sessionID, text, true)
      })
      .catch(() => watchers.delete(sessionID))
  }

  const stopWatch = (sessionID) => {
    const w = watchers.get(sessionID)
    watchers.delete(sessionID)
    if (w) w.kill()
  }

  // status reports an attention state ("" clears it). Fire-and-forget.
  const status = (sessionID, attention, detail) => {
    run("status", { ...payload(sessionID), attention, detail: detail ?? "" }, HOOK_TIMEOUT_MS).promise.catch(() => {})
  }

  // approve waits for the operator's decision on an asked permission and
  // replies with it; no decision leaves the terminal prompt to the user.
  const approve = (sessionID, perm) => {
    const id = perm && perm.id
    if (!id || approvals.has(id)) return
    const a = run("approve", { ...payload(sessionID), ...approveRequest(perm) }, APPROVE_TIMEOUT_MS)
    approvals.set(id, a)
    a.promise
      .then(async (text) => {
        if (approvals.get(id) !== a) return
        approvals.delete(id)
        const d = parseDecision(text)
        if (!d) return
        const response = d.decision === "allow" ? "once" : "reject"
        await client.postSessionIdPermissionsPermissionId({ path: { id: sessionID, permissionID: id }, body: { response } })
      })
      .catch(() => approvals.delete(id))
  }

  // abandon stops waiting on the console once the terminal answered.
  const abandon = (event) => {
    const p = (event && event.properties) || {}
    const id = p.requestID ?? p.permissionID
    const a = approvals.get(id)
    approvals.delete(id)
    if (a) a.kill()
  }

  return {
    event: async ({ event }) => {
      try {
        const sessionID = sessionOf(event)
        if (!sessionID) return
        switch (event.type) {
          case "session.error":
            status(sessionID, "failed", errorText(event))
            break
          case "permission.asked":
          case "permission.updated":
            status(sessionID, "blocked", permissionText(event))
            approve(sessionID, event.properties)
            break
          case "permission.replied":
            abandon(event)
            status(sessionID, "")
            break
          case "session.created":
            await inject("session-start", sessionID)
            break
          case "session.idle":
            startWatch(sessionID)
            break
          case "session.deleted":
            stopWatch(sessionID)
            agents.delete(sessionID)
            wakes.delete(sessionID)
            await run("session-end", payload(sessionID), HOOK_TIMEOUT_MS).promise
            break
        }
      } catch {}
    },
    "chat.message": async (input) => {
      try {
        const sessionID = input && input.sessionID
        if (!sessionID) return
        if (input.agent) agents.set(sessionID, input.agent)
        // A user turn supersedes any pending watch; the next idle restarts it.
        stopWatch(sessionID)
        // Not awaited: the prompt call must not block the message in flight.
        inject("prompt", sessionID).catch(() => {})
      } catch {}
    },
  }
}
